package com.miniforce.security;
import com.miniforce.model.User; import com.miniforce.repository.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.*; import io.jsonwebtoken.JwtException;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtService jwt; private final UserRepository users; public JwtAuthenticationFilter(JwtService j,UserRepository u){jwt=j;users=u;}
 @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain chain)throws ServletException,IOException {String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")) try {User u=users.findById(jwt.userId(h.substring(7))).orElse(null); if(u!=null){var auth=new UsernamePasswordAuthenticationToken(u,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name()))); SecurityContextHolder.getContext().setAuthentication(auth);}} catch(JwtException|IllegalArgumentException ignored){} chain.doFilter(r,s);}
}
